import json, sys
sys.path.insert(0, 'scripts')
from classify_h7 import *

with open('/root/autodl-tmp/outputs/plan001_exec_only_s44_1000_r2/eval_sta_results.json') as f:
    data = json.load(f)

results = data['results']
proved = [r for r in results if r.get('execution_reward', 0) == 1.0]

# Detailed classification
categories = {'h7a_only': [], 'h7b_only': [], 'h1_only': [], 'h8_only': [], 
              'h1_and_h8': [], 'genuine': [], 'other_combo': []}

for idx, r in enumerate(proved):
    details = r.get('details', {})
    premises = details.get('premises', [])
    conclusion = details.get('conclusion', '')
    isr = details.get('isr', 0)

    _h7a = is_h7_strict(premises, conclusion)
    _h7b = False if _h7a else is_h7b_obfuscated(premises, conclusion)
    _h1 = False if (_h7a or _h7b) else is_h1_strict(premises, conclusion)
    _h8 = is_h8_conjunction_collapse(premises, conclusion)

    flags = []
    if _h7a: flags.append('H7a')
    if _h7b: flags.append('H7b')
    if _h1: flags.append('H1')
    if _h8: flags.append('H8')

    rid = r.get('id', '?')
    entry = (rid, idx, len(premises), isr, conclusion[:60])

    if not flags:
        categories['genuine'].append(entry)
    elif flags == ['H1']:
        categories['h1_only'].append(entry)
    elif flags == ['H8']:
        categories['h8_only'].append(entry)
    elif flags == ['H1', 'H8']:
        categories['h1_and_h8'].append(entry)
    elif flags == ['H7a']:
        categories['h7a_only'].append(entry)
    else:
        categories['other_combo'].append((rid, flags))

print('=== s44-1000-r2 Classification Breakdown ===')
for cat, items in categories.items():
    print(f'{cat}: {len(items)}')

print(f'\\nVerification: H1_only({len(categories[\"h1_only\"])}) + H8_only({len(categories[\"h8_only\"])}) + H1_and_H8({len(categories[\"h1_and_h8\"])}) + genuine({len(categories[\"genuine\"])}) = {len(categories[\"h1_only\"])+len(categories[\"h8_only\"])+len(categories[\"h1_and_h8\"])+len(categories[\"genuine\"])}')

print(f'\\nGenuine proofs:')
for rid, idx, np, isr, concl in categories['genuine']:
    print(f'  {rid} (idx={idx}): {np} premises, ISR={isr}, concl={concl}')

print(f'\\nH1-and-H8 overlap:')
for rid, idx, np, isr, concl in categories['h1_and_h8']:
    print(f'  {rid} (idx={idx}): {np} premises, ISR={isr}, concl={concl}')

print(f'\\nH8-only (not H1):')
for rid, idx, np, isr, concl in categories['h8_only']:
    print(f'  {rid} (idx={idx}): {np} premises, ISR={isr}, concl={concl}')
